 PERFORM control.reconcile_preexecution_team_bindings('SS-LAUNCH-TEAM-001',proof);
 IF (SELECT count(*) FROM control.task_events WHERE task_id='SS-LAUNCH-TEAM-001' AND event_type='preexecution_verification_bindings_reconciled')<>1 THEN RAISE EXCEPTION 'Duplicate recovery event';END IF;
 IF EXISTS(SELECT 1 FROM control.executions WHERE task_id='SS-LAUNCH-TEAM-001') THEN RAISE EXCEPTION 'Configuration spent product attempt';END IF;
 IF (SELECT max_attempts FROM control.retry_policies WHERE policy_id='standard-five')<>5 THEN RAISE EXCEPTION 'Budget changed';END IF;
 BEGIN PERFORM control.reconcile_preexecution_team_bindings('SS-LAUNCH-TEAM-001',jsonb_set(proof,'{config,commands,0,required}','false')); RAISE EXCEPTION 'Weak binding accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='Weak binding accepted' THEN RAISE;END IF;END;
 PERFORM control.reconcile_ordinary_run_publication('55555555-2222-4333-8444-666666666666');
 IF NOT(control.current_run_publication_authority('SS-LAUNCH-TEAM-001')->>'authorized')::boolean THEN RAISE EXCEPTION 'Contract not refreshed';END IF;
 ex:=control.start_execution('SS-LAUNCH-TEAM-001','standard','fixture-model','medium','/tmp/fixture','codex/shop-suit/auth-fixture','stg',repeat('a',40));
 IF (SELECT attempt FROM control.executions WHERE execution_id=ex)<>1 THEN RAISE EXCEPTION 'Not initial dispatch';END IF;
 BEGIN PERFORM control.reconcile_preexecution_team_bindings('SS-LAUNCH-TEAM-001',proof); RAISE EXCEPTION 'Existing execution accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM='Existing execution accepted' THEN RAISE;END IF;END;
END $$;
